/* generated root CSS: 00-tokens/tokens.css */
/* ============================================================
   lab-ui · canonical tokens · light theme
   ----------------------------------------------------------------
   Source-of-truth design tokens for the the platform block catalog.
   Extracted from source tokens (example.com light theme) +
   additive --font-mono from v5 (JetBrains Mono).
   ============================================================ */

:root {
  /* ─── Palette (raw brand colors) ─────────────────────────── */
  --color-black:        #1B1D25;
  --color-white:        #FFFFFF;
  --color-gray:         #BEC5D3;
  --color-gray-second:  #5C6474;
  --color-gray-blue:    #97A2B8;
  --color-gray-light:   #D9D9D9;

  --color-cyan:         #6BEAF9;
  --color-blue:         #4F95FF;
  --color-red:          #FF6C56;
  --color-green:        #7DDE8E;
  --color-orange:       #FFA72C;
  --color-magenta:      #EF5CFF;

  --color-black-bg:           #17171B;
  --color-gray-bg:            #F9F9F9;
  --color-light-card-bg:      #F7F7F74D;
  --color-header-footer-bg:   rgba(77, 79, 104, 0.20);

  --color-dark-card-bg:       linear-gradient(180deg, #20232D 0%, #2C2D3C 100%);
  --color-light-gray-stroke:  linear-gradient(179.96deg, #E0E8F4 0.03%, #D1D6DD 102.68%);
  --color-dark-gray-stroke:   linear-gradient(180deg, #454F6B 0%, #2F2F40 100%);

  /* ─── Brand CTA rainbow gradient (locked: v5 direction + stops) */
  --gradient-cta-ring:
    linear-gradient(250deg,
      rgba(107, 237, 249, 0)   4.98%,
      #6bedf9                 37.35%,
      #ffa72c                 72.51%,
      rgba(239, 92, 255, 0)   96.41%);

  /* ─── Typography ─────────────────────────────────────────── */
  --font-family:        "Vela Sans", sans-serif;
  --font-mono:          "JetBrains Mono", ui-monospace, "SF Mono", Menlo, monospace;

  /* Type scale */
  --type-h1-size:       clamp(2.25rem, 5.2vw, 5rem);
  --type-h1-weight:     500;
  --type-h1-tracking:   -0.025em;
  --type-h1-leading:    1.04;

  --type-h2-size:       clamp(1.75rem, 3.4vw, 3.125rem);
  --type-h2-weight:     600;
  --type-h2-tracking:   -0.022em;
  --type-h2-leading:    1.15;

  --type-h3-size:       clamp(1.125rem, 1.6vw, 1.5625rem);
  --type-h3-weight:     600;
  --type-h3-tracking:   -0.015em;
  --type-h3-leading:    1.25;

  --type-h4-size:       1.125rem;
  --type-h4-weight:     600;
  --type-h4-tracking:   -0.01em;

  --type-lead-size:     clamp(1rem, 1.25vw, 1.25rem);
  --type-lead-weight:   400;
  --type-lead-leading:  1.5;

  --type-body-size:     1rem;
  --type-body-leading:  1.55;

  --type-eyebrow-size:  0.8125rem;
  --type-eyebrow-tracking: 0.12em;

  /* ─── Layout ─────────────────────────────────────────────── */
  --container-width:     105rem;
  --container-padding-x: 1.875rem;
  --header-height:       4.6875rem;

  /* Backdrop blur — header chrome */
  --backdrop-blur-header:    1.25rem;
  --backdrop-blur-table:     2.5rem;
  --backdrop-blur-ecosystem: 5rem;

  /* ─── Radii ──────────────────────────────────────────────── */
  --radius-pill:    6.25rem;
  --radius-card:    1.25rem;
  --radius-card-sm: 0.9375rem;

  /* ─── Motion ─────────────────────────────────────────────── */
  --transition-duration: 0.4s;
  --transition-fast:     0.2s;
  --transition-base:     var(--transition-duration);
  --transition-slow:     0.6s;

  /* ─── Elevation scale ────────────────────────────────────── */
  --shadow-1: 0 6px 16px -10px rgba(0, 0, 0, 0.18);
  --shadow-2: 0 14px 28px -22px rgba(0, 0, 0, 0.25);
  --shadow-3: 0 20px 48px -30px rgba(15, 17, 22, 0.28);
  --shadow-4: 0 24px 60px -26px rgba(27, 29, 37, 0.34);
  --shadow-glow: 0 0 32px -4px var(--cta-accent);          /* buttons + cards */
  --shadow-glow-soft: 0 0 18px -6px var(--cta-accent);      /* nav links, breadcrumb, locale chip */
  --shadow-glow-tight: 0 0 8px var(--cta-accent);           /* status / live dots */

  /* ─── Status palette (yes / partial / no / live) ─────────── */
  --color-status-yes:     #76D98F;
  --color-status-partial: #D7D9DC;
  --color-status-no:      #FF6B6B;
  --color-status-live:    #16A34A;

  /* ─── Surfaces · backdrop blur ───────────────────────────── */
  --backdrop-blur-panel: 1.125rem;  /* 18px — nav panel, table SW column */

  /* ─── Text accent (warm brown) ─────────────────────────────
     Pulled out so the first stop of --cta-secondary-fill is not
     re-used as a raw text color across blocks. */
  --color-text-accent:   #56422D;

  /* ─── Semantic tokens · LIGHT theme (canonical default) ──── */
  --color-bg:           var(--color-white);
  --color-bg-invert:    var(--color-black-bg);
  --color-text:         var(--color-gray-second);
  --color-heading:      var(--color-black);
  --color-link:         var(--color-black);
  --color-link-hover:   var(--color-gray-second);

  --header-bg:          var(--color-light-card-bg);
  --card-bg:            var(--color-gray-bg);
  --card-border:        var(--color-light-gray-stroke);
  --locale-selector-bg: var(--color-gray-bg);

  --button-primary-bg:        transparent;
  --button-primary-color:     var(--color-black);

  --button-secondary-bg:      transparent;
  --button-secondary-color:   var(--color-black);
  --button-secondary-border:  var(--color-black);

  --button-burger-button-bg:  var(--color-black);

  --input-bg:           var(--color-light-card-bg);

  /* ─── CTA · theme accent system ────────────────────────────
     --cta-accent is the page-wide interactive accent. It tints:
       · hover-rise glow (effect.hover-rise)
       · primary CTA outer hover glow (box-shadow)
       · secondary CTA always-on halo
       · italic accent word in hero titles
     --cta-secondary-fill is the filled background of secondary CTAs.
     Theme overrides go through [data-theme="..."] below. */
  --cta-accent:          var(--color-cyan);
  --cta-accent-soft:     rgba(107, 234, 249, 0.30);
  --cta-secondary-fill:  linear-gradient(90deg, #56422D 0%, #494938 100%);
  --cta-secondary-color: var(--color-white);
  --cta-secondary-border:rgba(255, 255, 255, 0.18);
}

/* ─── Theme overlays ───────────────────────────────────────────
   Set on <body data-theme="..."> or any wrapper. Cascades into
   every CTA, hover-rise effect, and accent text inside the scope.
   Names are color families, not industries — pick whichever fits. */

[data-theme="cyan"] {
  /* Default cyan — kept explicit so authors see the slot exists. */
  --cta-accent:          #6BEAF9;
  --cta-accent-soft:     rgba(107, 234, 249, 0.30);
  --cta-secondary-fill:  linear-gradient(90deg, #56422D 0%, #494938 100%);
}

[data-theme="green"] {
  --cta-accent:          #7DDE8E;
  --cta-accent-soft:     rgba(125, 222, 142, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #1E4D2F 0%, #2D5A3D 100%);
}

[data-theme="orange"] {
  --cta-accent:          #FFA72C;
  --cta-accent-soft:     rgba(255, 167, 44, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #5A3D1E 0%, #6B4A28 100%);
}

[data-theme="red"] {
  --cta-accent:          #FF6C56;
  --cta-accent-soft:     rgba(255, 108, 86, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #5A2D28 0%, #6B3A35 100%);
}

[data-theme="forest"] {
  --cta-accent:          #7DDE8E;
  --cta-accent-soft:     rgba(125, 222, 142, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #234728 0%, #345937 100%);
}

[data-theme="blue"] {
  --cta-accent:          #4F95FF;
  --cta-accent-soft:     rgba(79, 149, 255, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #1E3850 0%, #2C4A66 100%);
}

[data-theme="amber"] {
  --cta-accent:          #FFA72C;
  --cta-accent-soft:     rgba(255, 167, 44, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #4D3D1E 0%, #5C4A28 100%);
}

[data-theme="magenta"] {
  --cta-accent:          #EF5CFF;
  --cta-accent-soft:     rgba(239, 92, 255, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #3A2858 0%, #4B3370 100%);
}

/* ─── A11y · reduced motion ────────────────────────────────────
   Honour user's OS-level motion preference across every block. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

/* generated root CSS: 00-tokens/composition.css */
/* generated preview/CMS composition glue */
*, *::before, *::after {
  box-sizing: border-box;
}
html {
  min-width: 320px;
  scroll-behavior: smooth;
}
body {
  margin: 0;
  position: relative;
  min-width: 320px;
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
}
:root {
  --composition-section-y: clamp(4rem, 7vw, 6.5rem);
  --composition-section-y-compact: clamp(2.5rem, 5vw, 4rem);
}

/* Default vertical rhythm for every composed section.
   Blocks must NOT declare padding-block on their root class;
   the composer owns inter-section spacing.

   For section-wide decorative backgrounds (ambient tints, full-width
   surface colors): blocks declare the bg on the wrapper class
   `.composition-section--<block-id-slug>` so the fill extends through
   the composer-managed padding-block. The inner block class then owns
   content layout only. See hero.operational-diagram and
   mobile.4-card-glyph for canonical examples. */
.composition-section {
  position: relative;
  padding-block: var(--composition-section-y);
}

/* No edge-zero overrides: the hero needs padding-block-start so its
   content clears the sticky header (and the absolute-positioned
   breadcrumb chip that hangs from it), and the last section needs
   padding-block-end so it breathes above the footer. The default
   padding-block above gives both naturally. */

/* Closing accent sections are tighter at the top, with full rhythm
   at the bottom so the footer gets visual room. */
.composition-section--decorative-callout-band,
.composition-section--decorative-final-cta {
  padding-block: var(--composition-section-y-compact) var(--composition-section-y);
}
/* ─── Wrappers ───────────────────────────────────────────────
   Global wrapper primitive used by composer-injected markup AND
   by block-internal layouts that opt into `.container`. Block
   stylesheets may still redeclare `.<block> .container { … }`
   with the same calc — those are no-op duplicates but harmless. */
.container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

/* Narrow modifier for accent strips (callout, narrative). */
.container--narrow {
  max-width: calc(1100px + var(--container-padding-x) * 2);
}
a {
  color: inherit;
}
button,
input,
textarea,
select {
  font: inherit;
}
@media (max-width: 640px) {
  :root {
    --composition-section-y: 3.5rem;
    --composition-section-y-compact: 2.5rem;
  }
}

children.css:
/* generated child CSS: 03-cta/cta.btn-base/block.css */
/* lab-ui block · cta.btn-base
   Depends: 00-tokens/tokens.css (--radius-pill, --font-family,
   --transition-duration). Shared geometry + .btn-star base for every
   CTA variant. Variant blocks (cta.btn-primary-ring,
   cta.btn-secondary-filled) layer their own ::before/::after, halo
   shadows and color tokens on top. */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-width: 13rem;
  height: 3.25rem;
  padding: 0 1.625rem;
  border-radius: var(--radius-pill);
  font-family: var(--font-family);
  font-weight: 500;
  font-size: 1rem;
  white-space: nowrap;
  position: relative;
  text-decoration: none;
  cursor: pointer;
  border: 0;
  transition: box-shadow var(--transition-duration) ease,
              transform var(--transition-duration) ease;
}

.btn-star {
  flex-shrink: 0;
  transition: transform var(--transition-duration) cubic-bezier(.4, 0, .2, 1);
}


/* generated child CSS: 12-decorative/effect.hover-rise/block.css */
/* ============================================================
   lab-ui block · effect.hover-rise
   ----------------------------------------------------------------
   Brand interaction primitive — standard CTA halo + inner bottom-glow
   that fades in on :hover. Applied via CSS, no markup.

   ## Where it auto-applies (brand primitives)
   - .btn-primary-ring          (cta.btn-primary-ring)
   - .btn-secondary-filled      (cta.btn-secondary-filled)
   - .nav-link, .nav-trigger    (header.default nav items)
   - .locale-trigger            (language.locale-dropdown)
   - .bc-link                   (header.default breadcrumb)

   ## Opt-in for custom elements
   - [data-fx="rise"]

   ## Tint
   Default uses --cta-accent (which is --color-cyan by default and
   re-themed via [data-theme="..."] overlays). Override per element
   via --fx-rise-color: <color>.

   ## Implementation
   Each target element gets a ::after pseudo with the canonical
   bottom-centered radial glow used by current CTA blocks, plus an
   outer hover halo via box-shadow. No external image asset.

   ## Stacking
   Container must be position:relative (or rely on the host block
   making itself relative — all brand-primitive blocks already do).
   The ::after is z-index:1 with pointer-events:none so it never
   blocks interaction.
   ============================================================ */

:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
)::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 0;
  transform: translateX(-50%);
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
  border-radius: inherit;
  opacity: 0;
  transition: opacity var(--transition-duration, 0.25s) ease;

  /* Canonical inner glow: same bottom-centered radial used by
     cta.btn-primary-ring and cta.btn-secondary-filled. */
  background: radial-gradient(
    ellipse 58% 78% at 50% 100%,
    var(--fx-rise-color, var(--cta-accent, #6BEAF9)) 0%,
    transparent 60%
  );
  mix-blend-mode: normal;
  filter: none;
}

/* Activate on hover + on keyboard focus-visible (a11y). */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
):is(:hover, :focus-visible)::after {
  opacity: 0.48;
}

/* Brand-primitive base — they all need to be relative for the
   ::after to anchor inside. Each block also sets this in its own
   block.css, but we re-declare here so the effect works even when
   only this CSS is imported. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
) {
  position: relative;
  overflow: hidden;
  transition:
    box-shadow var(--transition-duration, 0.25s) ease,
    transform var(--transition-duration, 0.25s) ease;
}

/* Outer halo — two intensities so the same effect doesn't look
   aggressive on a 32 px nav link AND on a 52 px pill button.

   Strong (default): pills, cards, opt-in via [data-fx="rise"].
   Soft: header chrome — nav links, dropdown triggers, breadcrumb,
   locale chip. Override per element via --fx-rise-color. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  [data-fx="rise"]
):is(:hover, :focus-visible) {
  box-shadow: 0 0 32px -4px var(--fx-rise-color, var(--cta-accent, #6BEAF9));
}

:where(
  .nav-link,
  .nav-trigger,
  .locale-trigger
):is(:hover, :focus-visible) {
  box-shadow: 0 0 18px -6px var(--fx-rise-color, var(--cta-accent, #6BEAF9));
}

/* Keyboard-only focus ring (a11y). Distinct from the hover halo so that
   keyboard navigation is unambiguously visible — sighted hover users do
   not get the ring, only the soft glow. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
):focus-visible {
  outline: 2px solid var(--fx-rise-color, var(--cta-accent, #6BEAF9));
  outline-offset: 2px;
}

/* The hover-rise must stay BEHIND the element's own contents.
   We use overflow:hidden + ::after with z-index 1 — content sits
   at z-index 2. Brand primitives bump their direct children to
   z-index 2 here so we don't have to touch every block.css. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
) > * {
  position: relative;
  z-index: 2;
}

/* Reduced-motion: keep the effect but kill the transition so it
   appears instantly on hover with no animation. */
@media (prefers-reduced-motion: reduce) {
  :where(
    .btn-primary-ring,
    .btn-secondary-filled,
    .nav-link,
    .nav-trigger,
    .locale-trigger,
    .bc-link,
    [data-fx="rise"]
  )::after {
    transition: none;
  }
}


/* generated child CSS: 03-cta/cta.btn-primary-ring/block.css */
/* lab-ui block · cta.btn-primary-ring
   Depends: 00-tokens/tokens.css (--color-black, --radius-pill,
   --font-family, --gradient-cta-ring, --transition-duration,
   --cta-accent, --cta-accent-soft) + 03-cta/cta.btn-base (.btn, .btn-star). */

.btn-primary {
  background: var(--button-primary-bg, transparent);
  color: var(--button-primary-color, var(--color-black));
}

.btn-primary-ring {
  position: relative;
  overflow: hidden;
}

.btn-primary-ring::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1.5px;
  background: var(--gradient-cta-ring);
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask-composite: exclude;
  pointer-events: none;
  z-index: 3;                          /* above hover-rise ::after */
  transition: background var(--transition-duration) ease;
}

/* On hover the rainbow ring rotates direction 249° → 264° (matches
   live the platform .button-primary:hover::before). */
.btn-primary-ring:hover::before {
  background: linear-gradient(
    264.85deg,
    rgba(239, 92, 255, 0)   -6.54%,
    #FFA72C                 24.73%,
    #6BEDF9                 70.73%,
    rgba(107, 237, 249, 0) 113.1%
  );
}

/* Outer brand glow on hover — tighter than sw's stock 41 px so it
   reads as a halo hugging the pill, not a rectangular smear behind
   it (matches the production reference). Tinted by --cta-accent so
   each vertical paints its own color. */
.btn-primary-ring:hover {
  box-shadow: 0 0 32px -4px var(--cta-accent, #6BEAF9);
}

/* Match cta.btn-secondary-filled's hover affordance: a tighter
   bottom-centered radial glow that fades in, instead of the shared
   effect.hover-rise strip. The ring remains on ::before above it.
   Keep normal blending so the glow stays visible on white buttons. */
.btn-primary-ring::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: none;
  border-radius: inherit;
  pointer-events: none;
  z-index: 1;
  background: radial-gradient(
    ellipse 58% 78% at 50% 100%,
    var(--cta-accent, #6BEAF9) 0%,
    transparent 60%
  );
  opacity: 0;
  filter: none;
  background-blend-mode: normal;
  mix-blend-mode: normal;
  transition: opacity var(--transition-duration) ease;
}

.btn-primary-ring:hover::after {
  opacity: 0.48;
}

.btn-primary-ring:hover .btn-star {
  transform: rotate(180deg);
}


/* generated child CSS: 01-header/header.corporate-reference/block.css */
/* lab-ui block · header.corporate-reference
   Imported from CMS BlockTemplate 5ef64a49-2d1c-44df-873f-8e6f471e4b38 (HEADER). */

/* Source root reset/utilities scoped to imported header chrome. */
.header *,
.header *::before,
.header *::after {
  -webkit-box-sizing: border-box;
  box-sizing: border-box;
}

.header :where(ul, ol):where([class]) {
  padding-left: 0;
}

.header :where(h1, h2, h3, h4, h5, h6, p, ul, ol, dl):where([class]) {
  margin-block: 0;
}

.header :where(ul[class]) {
  list-style: none;
}

.header a:where([class]) {
  display: -webkit-inline-box;
  display: -ms-inline-flexbox;
  display: inline-flex;
}

.header a {
  color: var(--color-link);
  text-decoration: none;
}

.header :where(input, textarea, select, button) {
  font: inherit;
}

.header :where(button, label) {
  cursor: pointer;
}

.header :where(button) {
  -webkit-tap-highlight-color: transparent;
}

.header svg * {
  -webkit-transition-property: fill, stroke;
  -o-transition-property: fill, stroke;
  transition-property: fill, stroke;
}

.sr-only {
	clip: rect(0 0 0 0);
	-webkit-clip-path: inset(50%);
	clip-path: inset(50%);
	height: 1px;
	overflow: hidden;
	position: absolute;
	white-space: nowrap;
	width: 1px;
}

/* Source root mobile header-height variables used by imported HEADER. */
@media (width < 120rem) {
  :root {
    --header-height: 4.375rem;
  }
}

@media (width < 80rem) {
  :root {
    --header-height: 3.75rem;
  }
}

@media (width < 48rem) {
  :root {
    --header-height: 3.125rem;
  }
}

/* ─── Header ─────────────────────────────────── */
.header {
	position: sticky;
	top: 0;
	left: 0;
	width: 100%;
	z-index: 50;
	display: -webkit-box;
	display: -ms-flexbox;
	display: flex;
	-webkit-box-orient: vertical;
	-webkit-box-direction: normal;
	-ms-flex-direction: column;
	flex-direction: column;
	background-color: var(--header-bg);
	backdrop-filter: blur(var(--backdrop-blur-header));
	-webkit-backdrop-filter: blur(var(--backdrop-blur-header));
	border-bottom-left-radius: 2.5rem;
	border-bottom-right-radius: 2.5rem;
	overflow: visible;
    transition: background-color var(--transition-duration) ease;
}

.header-container {
	width: 100%;
}

.header-top {
	display: -webkit-box;
