/* imported header fragment CSS: HEADER_MENU (2dc1b800-000a-4217-9d3d-1a75dd21cd62) */
/* ─── Тематические настройки ─── */
:root[data-theme="dark"] {
  --res-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
  --res-item-hover: rgba(255, 255, 255, 0.05);
  --res-icon-bg: rgba(255, 255, 255, 0.03);
  --res-desc: rgba(255, 255, 255, 0.5);
}

:root[data-theme="light"] {
  --res-shadow: 0 15px 30px rgba(0, 0, 0, 0.08);
  --res-item-hover: rgba(0, 0, 0, 0.03);
  --res-icon-bg: rgba(0, 0, 0, 0.02);
  --res-desc: var(--color-gray-second);
}

.header-menu {
  margin-left: auto;
  margin-right: 30px;
}

.header-menu-list {
  display: flex;
  column-gap: 3.9375rem;
}

.header-menu-item {
  position: relative;
}

/* Свечение при ховере */
.header-menu-item::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  height: 100%;
  background-image: var(--menu-item-bg, none);
  background-repeat: no-repeat;
  background-position: center bottom;
  background-size: contain;
  opacity: 0;
  transition: opacity var(--transition-duration) cubic-bezier(0.34, 1.56, 0.64, 1);
  pointer-events: none;
  z-index: 1;
}

.header-menu-item:hover::after {
  opacity: 1;
}

.header-menu-link,
.resources-trigger {
  display: inline-flex;
  align-items: center;
  padding-inline: 0.625rem;
  height: var(--header-height);
  font-size: 1.25rem;
  color: var(--color-heading);
  transition: color var(--transition-duration) ease;
}

.resources-dropdown-wrapper {
  display: flex;
  align-items: center;
}

.resources-trigger {
  background: none;
  border: none;
  font-family: inherit;
  cursor: pointer;
  gap: 8px;
}

.resources-chevron {
  transition: transform 0.25s ease;
}

.resources-dropdown-wrapper.is-open .resources-chevron {
  transform: rotate(180deg);
}

.resources-menu-dropdown {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(10px);
  min-width: 580px;
  background-color: var(--locale-selector-bg);
  border-radius: 1.25rem;
  padding: 1.5rem;
  box-shadow: var(--res-shadow);
  border: 1px solid var(--card-border);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 1000;
}

.resources-menu-dropdown::before {
  content: "";
  position: absolute;
  top: -20px;
  left: 0;
  right: 0;
  height: 25px;
}

.resources-dropdown-wrapper.is-open .resources-menu-dropdown {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}

.resources-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.resource-item {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 0.875rem;
  border-radius: 0.75rem;
  text-decoration: none;
  transition: background-color 0.2s ease;
}

.resource-item:hover {
  background-color: var(--res-item-hover);
}

.resource-icon {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--res-icon-bg);
  border: 1px solid var(--card-border);
  border-radius: 10px;
  color: #6bc0f9;
}

.resource-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.resource-title {
  color: var(--color-heading);
  font-size: 1rem;
  font-weight: 500;
}

.resource-desc {
  color: var(--res-desc);
  font-size: 0.8125rem;
  line-height: 1.4;
}

/* ─── Industries Mega-Menu ─── */
.ind-mega-menu {
  min-width: 960px;
  left: 50%;
  transform: translateX(-50%) translateY(10px);
  padding: 0;
  overflow: hidden;
  display: flex;
}

.resources-dropdown-wrapper.is-open .ind-mega-menu {
  transform: translateX(-50%) translateY(0);
}

.ind-left {
  flex-shrink: 0;
  width: 268px;
  padding: 1rem 0.5rem;
  border-right: 1px solid var(--card-border);
}

.ind-nav-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ind-nav-item {
  list-style: none;
}

.ind-nav-btn {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  width: 100%;
  padding: 0.625rem 0.75rem;
  border: none;
  background: none;
  border-radius: 0.625rem;
  cursor: pointer;
  color: var(--color-heading);
  font-size: 0.9375rem;
  font-weight: 400;
  text-align: left;
  transition: background-color 0.18s ease, color 0.18s ease;
}

.ind-nav-btn:hover,
.ind-nav-item.is-active .ind-nav-btn {
  background-color: rgba(90, 79, 207, 0.07);
  color: #5a4fcf;
}

:root[data-theme="dark"] .ind-nav-btn:hover,
:root[data-theme="dark"] .ind-nav-item.is-active .ind-nav-btn {
  background-color: rgba(107, 79, 207, 0.15);
  color: #9b8df5;
}

.ind-nav-icon {
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: inherit;
  opacity: 0.7;
}

.ind-nav-item.is-active .ind-nav-icon,
.ind-nav-btn:hover .ind-nav-icon {
  opacity: 1;
}

.ind-nav-label {
  flex: 1;
  line-height: 1.3;
}

.ind-nav-chevron {
  flex-shrink: 0;
  opacity: 0;
  transition: opacity 0.18s ease;
  color: inherit;
}

.ind-nav-btn:hover .ind-nav-chevron,
.ind-nav-item.is-active .ind-nav-chevron {
  opacity: 1;
}

/* Right panel */
.ind-right {
  flex: 1;
  position: relative;
  min-height: 420px;
}

.ind-panel {
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
}

.ind-panel.is-active {
  opacity: 1;
  pointer-events: auto;
}

/* Default panel */
.ind-panel--default {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 2.5rem;
  text-align: center;
  gap: 0.5rem;
}

.ind-default-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: rgba(90, 79, 207, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.5rem;
}

:root[data-theme="dark"] .ind-default-icon {
  background: rgba(107, 79, 207, 0.2);
}

.ind-default-title {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--color-heading);
  margin-bottom: 0.25rem;
}

.ind-default-desc {
  font-size: 0.9375rem;
  color: var(--res-desc);
  max-width: 280px;
}

.ind-default-sub {
  font-size: 0.875rem;
  color: var(--res-desc);
  max-width: 280px;
  margin-top: 0.25rem;
}

/* Industry content panel */
.ind-panel--industry {
  display: flex;
  align-items: flex-start;
  gap: 0;
  padding: 1.75rem 1.5rem 1.75rem 1.75rem;
}

.ind-industry-desc {
  flex: 0 0 300px;
  padding-right: 1.5rem;
  border-right: 1px solid var(--card-border);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  align-self: stretch;
}

.ind-industry-label {
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #5a4fcf;
}

:root[data-theme="dark"] .ind-industry-label {
  color: #9b8df5;
}

.ind-industry-title {
  font-size: 1.375rem;
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-heading);
}

.ind-industry-body {
  font-size: 0.875rem;
  color: var(--res-desc);
  line-height: 1.5;
  flex: 1;
}

.ind-cta-link {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.9375rem;
  font-weight: 500;
  color: #5a4fcf;
  text-decoration: none;
  margin-top: 0.5rem;
  transition: gap 0.2s ease, opacity 0.2s ease;
}

:root[data-theme="dark"] .ind-cta-link {
  color: #9b8df5;
}

.ind-cta-link:hover {
  gap: 0.5rem;
  opacity: 0.8;
}

.ind-cta-link--outline {
  border: 1.5px solid #5a4fcf;
  border-radius: 100px;
  padding: 0.5rem 1.25rem;
  margin-top: 0.75rem;
  color: #5a4fcf;
}

:root[data-theme="dark"] .ind-cta-link--outline {
  border-color: #9b8df5;
  color: #9b8df5;
}

.ind-cta-link--outline:hover {
  background: rgba(90, 79, 207, 0.06);
}

/* Sub-items list */
.ind-sub-list {
  flex: 1;
  padding-left: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1px;
  list-style: none;
  align-self: flex-start;
  max-height: 380px;
  overflow-y: auto;
}

.ind-sub-item {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.5rem 0.625rem;
  border-radius: 0.5rem;
  text-decoration: none;
  color: var(--color-heading);
  font-size: 0.9375rem;
  transition: background-color 0.18s ease;
}

.ind-sub-item:hover {
  background-color: var(--res-item-hover);
}

.ind-sub-icon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #5a4fcf;
}

:root[data-theme="dark"] .ind-sub-icon {
  color: #9b8df5;
}

.ind-sub-item span:not(.ind-sub-icon):not(.ind-badge) {
  flex: 1;
}

.ind-sub-arrow {
  flex-shrink: 0;
  color: var(--color-gray);
  opacity: 0;
  transition: opacity 0.18s ease;
}

.ind-sub-item:hover .ind-sub-arrow {
  opacity: 1;
}

.ind-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 7px;
  border-radius: 100px;
  font-size: 0.6875rem;
  font-weight: 600;
  background: rgba(90, 79, 207, 0.1);
  color: #5a4fcf;
  margin-left: 0.375rem;
}

:root[data-theme="dark"] .ind-badge {
  background: rgba(155, 141, 245, 0.15);
  color: #9b8df5;
}

/* Media Queries */
@media (width < 120rem) {
  .header-menu-list {
    column-gap: 1.5625rem;
  }
  .header-menu-link,
  .resources-trigger {
    font-size: 1rem;
  }
}

@media (width < 90rem) {
  .header-menu {
    margin-inline: 0;
  }
  .header-menu-list {
    column-gap: 1rem;
  }
  .header-menu-link,
  .resources-trigger {
    font-size: 0.875rem;
  }
  .resources-menu-dropdown {
    min-width: 500px;
  }
}

@media (width < 80rem) {
  .header-menu {
    display: none;
  }
}

/* imported header fragment CSS: LOCALE_SELECTOR (f7488eae-006f-4c4c-bc4b-53ba7e1968d3) */
.locale-selector {
  position: relative;
  display: inline-block;
  line-height: 1.35;
  letter-spacing: -0.01em;
  z-index: 100;
  isolation: isolate;
}

.locale-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding-inline: 15px;
  height: 42px;
  border: none;
  border-radius: 10px;
  background-color: var(--header-bg);
  color: var(--color-heading);
  font-size: 1rem;
  font-weight: 400;
  letter-spacing: -0.01em;
  cursor: pointer;
  white-space: nowrap;
  position: relative;
  min-width: 180px;
  transition: border-radius 0.2s ease;
}

.locale-trigger-left {
  display: flex;
  align-items: center;
  gap: 6px;
}

/* Эффект открытого меню для кнопки */
.locale-selector.is-open .locale-trigger {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

.locale-selector.is-open .locale-chevron {
  transform: rotate(180deg);
}

.locale-chevron {
  flex-shrink: 0;
  transition: transform var(--transition-duration) cubic-bezier(0.4, 0, 0.2, 1);
}

.locale-dropdown {
  position: absolute;
  top: 100%; /* Прижимаем к низу триггера */
  left: 0;
  min-width: 100%;
  background-color: var(--locale-selector-bg);
  border-bottom-right-radius: 1.25rem;
  border-bottom-left-radius: 1.25rem;
  overflow: hidden;
  z-index: 9999;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(10px); /* Начальное смещение как у Resources */
  transition:
    opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1),
    transform 0.25s cubic-bezier(0.4, 0, 0.2, 1),
    visibility 0.25s;
}

/* Невидимый мостик, чтобы меню не закрывалось при движении мыши вниз */
.locale-dropdown::before {
  content: "";
  position: absolute;
  top: -20px;
  left: 0;
  right: 0;
  height: 25px;
  background: transparent;
}

.locale-selector.is-open .locale-dropdown {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateY(0);
}

.locale-list {
  list-style: none;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  max-height: 304px;
  overflow-y: auto;
  padding: 0;
}

.locale-item {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.625rem 0.875rem;
  color: var(--color-heading);
  font-size: 1rem;
  font-weight: 400;
  cursor: pointer;
  white-space: nowrap;
  position: relative;
  opacity: 0;
  transform: translateX(-4px);
  transition: opacity 0.2s ease,
              transform 0.2s ease,
              background-color var(--transition-duration) ease;
}

.locale-selector.is-open .locale-item {
  opacity: 1;
  transform: translateX(0);
}

/* Твои задержки анимации */
.locale-selector.is-open .locale-item:nth-child(1) { transition-delay: 0.04s; }
.locale-selector.is-open .locale-item:nth-child(2) { transition-delay: 0.07s; }
.locale-selector.is-open .locale-item:nth-child(3) { transition-delay: 0.10s; }
.locale-selector.is-open .locale-item:nth-child(4) { transition-delay: 0.13s; }
.locale-selector.is-open .locale-item:nth-child(5) { transition-delay: 0.16s; }
.locale-selector.is-open .locale-item:nth-child(6) { transition-delay: 0.19s; }

.locale-item:hover {
  background-color: rgba(255, 255, 255, 0.06);
}

.locale-item.is-active {
  background-color: rgba(107, 192, 249, 0.1);
}

.locale-item-label {
  font-size: 1rem;
  flex: 1;
}

.locale-check {
  width: 0.875rem;
  height: 0.875rem;
  flex-shrink: 0;
  color: #6BC0F9;
  opacity: 0;
  transform: scale(0.6);
  transition:
    opacity 0.2s ease,
    transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.locale-item.is-active .locale-check {
  opacity: 1;
  transform: scale(1);
}

.flag-icon {
  width: 20px !important;
  height: 12px !important;
  flex-shrink: 0;
}

@media (width < 90rem) {
  .locale-trigger { font-size: 12px; }
  .locale-item-label { font-size: 12px; }
}

@media (width < 80rem) {
  .locale-selector { display: none; }
}

