/* generated child CSS: 03-cta/cta.btn-base/block.css */
/* lab-ui block · cta.btn-base
   Depends: 00-tokens/tokens.css (--radius-pill, --font-family,
   --transition-duration). Shared geometry + .btn-star base for every
   CTA variant. Variant blocks (cta.btn-primary-ring,
   cta.btn-secondary-filled) layer their own ::before/::after, halo
   shadows and color tokens on top. */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-width: 13rem;
  height: 3.25rem;
  padding: 0 1.625rem;
  border-radius: var(--radius-pill);
  font-family: var(--font-family);
  font-weight: 500;
  font-size: 1rem;
  white-space: nowrap;
  position: relative;
  text-decoration: none;
  cursor: pointer;
  border: 0;
  transition: box-shadow var(--transition-duration) ease,
              transform var(--transition-duration) ease;
}

.btn-star {
  flex-shrink: 0;
  transition: transform var(--transition-duration) cubic-bezier(.4, 0, .2, 1);
}


/* generated child CSS: 12-decorative/effect.hover-rise/block.css */
/* ============================================================
   lab-ui block · effect.hover-rise
   ----------------------------------------------------------------
   Brand interaction primitive — standard CTA halo + inner bottom-glow
   that fades in on :hover. Applied via CSS, no markup.

   ## Where it auto-applies (brand primitives)
   - .btn-primary-ring          (cta.btn-primary-ring)
   - .btn-secondary-filled      (cta.btn-secondary-filled)
   - .nav-link, .nav-trigger    (header.default nav items)
   - .locale-trigger            (language.locale-dropdown)
   - .bc-link                   (header.default breadcrumb)

   ## Opt-in for custom elements
   - [data-fx="rise"]

   ## Tint
   Default uses --cta-accent (which is --color-cyan by default and
   re-themed via [data-theme="..."] overlays). Override per element
   via --fx-rise-color: <color>.

   ## Implementation
   Each target element gets a ::after pseudo with the canonical
   bottom-centered radial glow used by current CTA blocks, plus an
   outer hover halo via box-shadow. No external image asset.

   ## Stacking
   Container must be position:relative (or rely on the host block
   making itself relative — all brand-primitive blocks already do).
   The ::after is z-index:1 with pointer-events:none so it never
   blocks interaction.
   ============================================================ */

:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
)::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 0;
  transform: translateX(-50%);
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
  border-radius: inherit;
  opacity: 0;
  transition: opacity var(--transition-duration, 0.25s) ease;

  /* Canonical inner glow: same bottom-centered radial used by
     cta.btn-primary-ring and cta.btn-secondary-filled. */
  background: radial-gradient(
    ellipse 58% 78% at 50% 100%,
    var(--fx-rise-color, var(--cta-accent, #6BEAF9)) 0%,
    transparent 60%
  );
  mix-blend-mode: normal;
  filter: none;
}

/* Activate on hover + on keyboard focus-visible (a11y). */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
):is(:hover, :focus-visible)::after {
  opacity: 0.48;
}

/* Brand-primitive base — they all need to be relative for the
   ::after to anchor inside. Each block also sets this in its own
   block.css, but we re-declare here so the effect works even when
   only this CSS is imported. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
) {
  position: relative;
  overflow: hidden;
  transition:
    box-shadow var(--transition-duration, 0.25s) ease,
    transform var(--transition-duration, 0.25s) ease;
}

/* Outer halo — two intensities so the same effect doesn't look
   aggressive on a 32 px nav link AND on a 52 px pill button.

   Strong (default): pills, cards, opt-in via [data-fx="rise"].
   Soft: header chrome — nav links, dropdown triggers, breadcrumb,
   locale chip. Override per element via --fx-rise-color. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  [data-fx="rise"]
):is(:hover, :focus-visible) {
  box-shadow: 0 0 32px -4px var(--fx-rise-color, var(--cta-accent, #6BEAF9));
}

:where(
  .nav-link,
  .nav-trigger,
  .locale-trigger
):is(:hover, :focus-visible) {
  box-shadow: 0 0 18px -6px var(--fx-rise-color, var(--cta-accent, #6BEAF9));
}

/* Keyboard-only focus ring (a11y). Distinct from the hover halo so that
   keyboard navigation is unambiguously visible — sighted hover users do
   not get the ring, only the soft glow. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
):focus-visible {
  outline: 2px solid var(--fx-rise-color, var(--cta-accent, #6BEAF9));
  outline-offset: 2px;
}

/* The hover-rise must stay BEHIND the element's own contents.
   We use overflow:hidden + ::after with z-index 1 — content sits
   at z-index 2. Brand primitives bump their direct children to
   z-index 2 here so we don't have to touch every block.css. */
:where(
  .btn-primary-ring,
  .btn-secondary-filled,
  .nav-link,
  .nav-trigger,
  .locale-trigger,
  .bc-link,
  [data-fx="rise"]
) > * {
  position: relative;
  z-index: 2;
}

/* Reduced-motion: keep the effect but kill the transition so it
   appears instantly on hover with no animation. */
@media (prefers-reduced-motion: reduce) {
  :where(
    .btn-primary-ring,
    .btn-secondary-filled,
    .nav-link,
    .nav-trigger,
    .locale-trigger,
    .bc-link,
    [data-fx="rise"]
  )::after {
    transition: none;
  }
}


/* generated child CSS: 03-cta/cta.btn-primary-ring/block.css */
/* lab-ui block · cta.btn-primary-ring
   Depends: 00-tokens/tokens.css (--color-black, --radius-pill,
   --font-family, --gradient-cta-ring, --transition-duration,
   --cta-accent, --cta-accent-soft) + 03-cta/cta.btn-base (.btn, .btn-star). */

.btn-primary {
  background: var(--button-primary-bg, transparent);
  color: var(--button-primary-color, var(--color-black));
}

.btn-primary-ring {
  position: relative;
  overflow: hidden;
}

.btn-primary-ring::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1.5px;
  background: var(--gradient-cta-ring);
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask-composite: exclude;
  pointer-events: none;
  z-index: 3;                          /* above hover-rise ::after */
  transition: background var(--transition-duration) ease;
}

/* On hover the rainbow ring rotates direction 249° → 264° (matches
   live the platform .button-primary:hover::before). */
.btn-primary-ring:hover::before {
  background: linear-gradient(
    264.85deg,
    rgba(239, 92, 255, 0)   -6.54%,
    #FFA72C                 24.73%,
    #6BEDF9                 70.73%,
    rgba(107, 237, 249, 0) 113.1%
  );
}

/* Outer brand glow on hover — tighter than sw's stock 41 px so it
   reads as a halo hugging the pill, not a rectangular smear behind
   it (matches the production reference). Tinted by --cta-accent so
   each vertical paints its own color. */
.btn-primary-ring:hover {
  box-shadow: 0 0 32px -4px var(--cta-accent, #6BEAF9);
}

/* Match cta.btn-secondary-filled's hover affordance: a tighter
   bottom-centered radial glow that fades in, instead of the shared
   effect.hover-rise strip. The ring remains on ::before above it.
   Keep normal blending so the glow stays visible on white buttons. */
.btn-primary-ring::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: none;
  border-radius: inherit;
  pointer-events: none;
  z-index: 1;
  background: radial-gradient(
    ellipse 58% 78% at 50% 100%,
    var(--cta-accent, #6BEAF9) 0%,
    transparent 60%
  );
  opacity: 0;
  filter: none;
  background-blend-mode: normal;
  mix-blend-mode: normal;
  transition: opacity var(--transition-duration) ease;
}

.btn-primary-ring:hover::after {
  opacity: 0.48;
}

.btn-primary-ring:hover .btn-star {
  transform: rotate(180deg);
}


/* generated child CSS: 03-cta/cta.btn-secondary-filled/block.css */
/* lab-ui block · cta.btn-secondary-filled
   Depends: 00-tokens/tokens.css
     (--cta-secondary-fill, --cta-secondary-color, --cta-secondary-border,
      --cta-accent-soft, --radius-pill, --font-family, --transition-duration)
   + 03-cta/cta.btn-base (.btn, .btn-star)
   + 12-decorative/effect.hover-rise (inner bottom glow). */

.btn-secondary-filled {
  /* Filled background — re-themed per vertical via tokens */
  background: var(--cta-secondary-fill);
  color: var(--cta-secondary-color);
  border: 1px solid var(--cta-secondary-border);

  /* Idle: no glow at all. Both halos fade in only on :hover. */
  box-shadow: none;

  transition: box-shadow var(--transition-duration) ease;
  position: relative;
  overflow: hidden;        /* keeps ::before contained */
}

/* Inner glow — radial-gradient ellipse pinned to the bottom-center.
   ~58 % wide so the rounded end caps stay dark even when active.
   Lives in the DOM at all times but starts at opacity 0; fades in
   on :hover (along with the outer halo) so the pill looks "lit"
   under the cursor and quiet at rest. */
.btn-secondary-filled::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  z-index: 1;
  background: radial-gradient(
    ellipse 58% 78% at 50% 100%,
    var(--cta-accent, #6BEAF9) 0%,
    transparent 60%
  );
  opacity: 0;
  mix-blend-mode: screen;
  transition: opacity var(--transition-duration) ease;
}

.btn-secondary-filled:hover {
  /* Outer halo fades in on hover. Spread -4 px + blur 32 px gives
     a round soft glow that hugs the pill instead of smearing
     rectangularly. Tinted by current vertical's --cta-accent. */
  box-shadow: 0 0 32px -4px var(--cta-accent, #6BEAF9);
}

.btn-secondary-filled:hover::before {
  /* Inner radial fades in to match the outer halo. */
  opacity: 0.48;
}

/* Suppress the auto-applied effect.hover-rise ::after on this block —
   we draw a tighter, 65 %-wide bottom glow via ::before that already
   covers the same affordance. Stacking both reads as "double glow". */
.btn-secondary-filled::after {
  display: none;
}

.btn-secondary-filled .btn-star {
  flex-shrink: 0;
  color: var(--cta-secondary-color);
  transition: transform var(--transition-duration) cubic-bezier(.4,0,.2,1);
}
.btn-secondary-filled:hover .btn-star {
  transform: rotate(180deg);
}


/* generated child CSS: 05-hero/hero.composite-photo/block.css */
/* lab-ui block · hero.composite-photo
   Depends: 00-tokens/tokens.css. Light theme.
   Composes: cta.btn-base + cta.btn-primary-ring + cta.btn-secondary-filled. */

.herop {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
}
.herop-grid {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  gap: clamp(2rem, 5vw, 4rem);
  align-items: center;
}

.herop-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-mono);
  font-size: var(--type-eyebrow-size);
  letter-spacing: var(--type-eyebrow-tracking);
  text-transform: uppercase;
  color: var(--color-gray-blue);
  padding: 6px 12px;
  background: var(--color-gray-bg);
  border-radius: 999px;
  margin-bottom: 22px;
}
.herop-eyebrow .crumb-sep { color: var(--color-gray-light); }
.herop-eyebrow .crumb-cur { color: var(--color-heading); font-weight: 500; }

.herop-title {
  margin: 0 0 24px;
  font-weight: var(--type-h1-weight);
  font-size: var(--type-h1-size);
  line-height: var(--type-h1-leading);
  letter-spacing: var(--type-h1-tracking);
  color: var(--color-heading);
}
.herop-title .accent {
  font-style: italic;
  color: var(--color-blue);
}

.herop-leads { display: grid; gap: 14px; max-width: 36rem; margin-bottom: 28px; }
.herop-leads p {
  margin: 0;
  font-size: var(--type-lead-size);
  line-height: var(--type-lead-leading);
  color: var(--color-text);
}

.herop-cta { display: flex; gap: 12px; flex-wrap: wrap; }

/* ─── Photo composite ─────────────────────────────────────── */
.herop-art {
  position: relative;
  width: 100%;
  aspect-ratio: 5 / 6;
  border-radius: var(--radius-card);
  overflow: hidden;
  background: var(--color-gray-bg);
}
.herop-photo,
.herop-photo svg,
.herop-photo img,
.herop-photo-placeholder {
  position: absolute; inset: 0;
  width: 100%; height: 100%;
  object-fit: cover;
}

.herop-photo-placeholder {
  z-index: 1;
  pointer-events: none;
  display: grid;
  place-content: center;
  place-items: center;
  gap: 14px;
  padding: 32px;
  text-align: center;
  font-family: var(--font-mono, monospace);
  color: #5C6474;
  font-size: clamp(0.875rem, 2vw, 1.125rem);
  line-height: 1.55;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  background:
    repeating-linear-gradient(
      135deg,
      rgba(255,255,255,0.22) 0,
      rgba(255,255,255,0.22) 12px,
      rgba(215,226,236,0.16) 12px,
      rgba(215,226,236,0.16) 24px
    ),
    linear-gradient(180deg, #EAF3F8 0%, #F4F8FB 100%);
}

.herop-photo-img[src=""],
.herop-photo-img[src="#"],
.herop-photo-img[src^="/core/image//"],
.herop-photo-img[src$="/get"],
.herop-photo-img[src$="/get/"],
.herop-photo-img[src*="/get//"] {
  opacity: 0;
}

.herop-photo-img {
  display: block;
  z-index: 2;
}

.herop-photo-img[src]:not([src=""]):not([src="#"]):not([src^="/core/image//"]):not([src$="/get"]):not([src$="/get/"]):not([src*="/get//"]) + .herop-photo-placeholder {
  display: none;
}

.herop-photo-placeholder span {
  display: block;
}

/* Dark stat chip — bottom-left overlay */
.herop-chip {
  position: absolute;
  z-index: 3;
  left: 20px;
  bottom: 80px;
  background: var(--color-black-bg);
  color: var(--color-white);
  padding: 14px 18px;
  border-radius: 16px;
  display: grid;
  gap: 4px;
  min-width: 140px;
  box-shadow: 0 14px 32px -16px rgba(0,0,0,0.4);
}
.herop-chip-num {
  font-family: var(--font-mono);
  font-size: 1.625rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--color-cyan);
  line-height: 1;
}
.herop-chip-label {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-gray);
}

/* Person cards — right-side overlays */
.herop-person {
  position: absolute;
  z-index: 3;
  background: var(--color-bg);
  border: 1px solid rgba(0,0,0,0.06);
  border-radius: 14px;
  padding: 10px 14px 10px 10px;
  display: flex; align-items: center; gap: 10px;
  box-shadow: 0 12px 24px -16px rgba(0,0,0,0.25);
  min-width: 180px;
}
.herop-person--1 { top: 32px;  right: 24px; }
.herop-person--2 { top: 124px; right: 60px; }

.herop-person-avatar { position: relative; width: 36px; height: 36px; border-radius: 999px; overflow: hidden; flex: 0 0 auto; }
.herop-person-avatar svg,
.herop-person-avatar img { width: 100%; height: 100%; display: block; object-fit: cover; }
.herop-person-avatar-img,
.herop-person-avatar-fallback { position: absolute; inset: 0; }
.herop-person-avatar-img { z-index: 1; }
.herop-person-avatar-fallback { z-index: 0; }
.herop-person-avatar-img[src=""],
.herop-person-avatar-img[src="#"],
.herop-person-avatar-img[src^="/core/image//"],
.herop-person-avatar-img[src$="/get"],
.herop-person-avatar-img[src$="/get/"],
.herop-person-avatar-img[src*="/get//"] {
  opacity: 0;
}
.herop-person-avatar-img[src]:not([src=""]):not([src="#"]):not([src^="/core/image//"]):not([src$="/get"]):not([src$="/get/"]):not([src*="/get//"]) + .herop-person-avatar-fallback {
  display: none;
}
.herop-person-name {
  margin: 0;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-heading);
  line-height: 1.2;
}
.herop-person-role {
  margin: 2px 0 0;
  font-family: var(--font-mono);
  font-size: 0.625rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-gray-blue);
}

@media (max-width: 980px) {
